import { ArrowRight, Bot, Check, CornerDownLeft, MessageSquareText, RotateCcw, Sparkles, UserRound } from 'lucide-react'
import { useState, type FormEvent } from 'react'
import { useMemory } from '../state/MemoryContext'
import styles from './UtilityPages.module.css'

export function ChatPage() {
  const { workspace, applyCorrection } = useMemory()
  const [draft, setDraft] = useState('')
  const [message, setMessage] = useState<string | null>(null)

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const nextMessage = draft.trim()
    if (!nextMessage) return
    setMessage(nextMessage)
    setDraft('')
  }

  const correction = workspace.correction

  return (
    <section className={styles.page} aria-labelledby="chat-title">
      <header className={styles.pageHeader}>
        <div>
          <span className={styles.eyebrow}>CONVERSATION MEMORY</span>
          <h1 id="chat-title">대화하면서, 기억을 바로잡으세요</h1>
          <p>틀린 이해를 발견하면 흐름을 끊지 않고 수정 범위를 선택할 수 있습니다.</p>
        </div>
        <div className={styles.headerStatus}><span /> MEMORY LISTENING</div>
      </header>

      <div className={styles.chatGrid}>
        <section className={`${styles.panel} ${styles.conversation}`} aria-label="AI 대화">
          <div className={styles.panelHeader}>
            <div className={styles.panelIdentity}><span className={styles.iconTile}><Bot size={16} /></span><div><strong>Memory Assistant</strong><small>개인 기억을 사용 중</small></div></div>
            <span className={styles.online}><i /> ONLINE</span>
          </div>

          <div className={styles.thread} aria-live="polite">
            <div className={styles.dateDivider}><span>오늘</span></div>
            <div className={styles.assistantMessage}>
              <span className={styles.avatar}><Sparkles size={14} /></span>
              <div><p>최근 프로젝트 흐름을 보면 Flutter를 주로 사용하시는 것 같아요. 다음 모바일 프로젝트도 Flutter 기준으로 정리해 드릴까요?</p><time>오후 3:14</time></div>
            </div>
            {message && (
              <>
                <div className={styles.userMessage}>
                  <div><p>{message}</p><time>방금</time></div>
                  <span className={`${styles.avatar} ${styles.userAvatar}`}><UserRound size={14} /></span>
                </div>
                <div className={styles.assistantMessage}>
                  <span className={styles.avatar}><Sparkles size={14} /></span>
                  <div><p>알겠습니다. 최근 사용 빈도가 줄었다는 점을 반영할 수 있어요. 이 수정이 적용될 범위를 선택해 주세요.</p><time>방금</time></div>
                </div>
              </>
            )}
          </div>

          <form className={styles.composer} onSubmit={submit}>
            <MessageSquareText size={16} aria-hidden="true" />
            <input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="메시지를 입력하세요" aria-label="메시지" />
            <span className={styles.keyHint}>ENTER</span>
            <button type="submit" aria-label="메시지 보내기"><CornerDownLeft size={15} /></button>
          </form>
        </section>

        <aside className={styles.inspector} aria-label="기억 수정 제안">
          <div className={styles.inspectorIntro}>
            <span className={styles.iconTile}><RotateCcw size={15} /></span>
            <div><span className={styles.eyebrow}>MEMORY PATCH</span><h2>대화 속 수정</h2></div>
          </div>

          {!message ? (
            <div className={styles.emptyState}>
              <div className={styles.emptyOrbit}><span /><MessageSquareText size={19} /></div>
              <strong>수정 신호를 기다리는 중</strong>
              <p>AI의 이해가 틀렸을 때 자연스럽게 말해 주세요. 기억 변경 후보를 이곳에 표시합니다.</p>
            </div>
          ) : (
            <div className={styles.correctionCard}>
              <div className={styles.detected}><Sparkles size={13} /><span><strong>기억 수정 감지</strong><small>신뢰도 94%</small></span></div>
              <div className={styles.changePreview}>
                <span>BEFORE</span><p>{correction.before}</p>
                <ArrowRight size={14} />
                <span>AFTER</span><p>{correction.after}</p>
              </div>
              <div className={styles.scopeNote}><Check size={13} /><span><strong>수정 범위를 선택하세요</strong><small>선택 후에도 Memory 화면에서 되돌릴 수 있습니다.</small></span></div>
              <div className={styles.correctionActions}>
                <button type="button" className={styles.primaryButton} onClick={() => void applyCorrection(correction.id, 'global')}>모든 대화에 반영</button>
                <button type="button" className={styles.secondaryButton} onClick={() => void applyCorrection(correction.id, 'conversation')}>이 대화에만</button>
                <button type="button" className={styles.textButton} onClick={() => void applyCorrection(correction.id, 'ignore')}>무시</button>
              </div>
            </div>
          )}

          <div className={styles.inspectorFooter}><span>수정된 기억은 다음 응답부터 사용됩니다.</span><b>LOCAL FIRST</b></div>
        </aside>
      </div>
    </section>
  )
}

import { Bot, Braces, BriefcaseBusiness, Check, Code2, LockKeyhole, Palette, ShieldCheck, UserRound } from 'lucide-react'
import { useState } from 'react'
import type { MemoryCategory } from '../domain/memory'
import { useMemory } from '../state/MemoryContext'
import styles from './UtilityPages.module.css'

const categories: Array<{ name: MemoryCategory; icon: typeof Code2; note: string }> = [
  { name: '코딩', icon: Code2, note: '스택, 도구, 개발 습관' },
  { name: '일', icon: BriefcaseBusiness, note: '프로젝트, 목표, 업무 방식' },
  { name: '취향', icon: Palette, note: '디자인, 표현, 선호' },
  { name: '개인', icon: UserRound, note: '생활, 신상, 개인 맥락' },
]

const appMeta: Record<string, { icon: typeof Bot; description: string; badge: string }> = {
  ChatGPT: { icon: Bot, description: '기본 대화 및 프로젝트', badge: 'OPENAI' },
  '회사 AI': { icon: BriefcaseBusiness, description: '조직에서 관리하는 어시스턴트', badge: 'WORK' },
  '코딩 어시스턴트': { icon: Braces, description: 'IDE와 연결된 개발 도구', badge: 'LOCAL' },
}

export function AccessPage() {
  const { workspace, updateAccess } = useMemory()
  const [overrides, setOverrides] = useState<Record<string, boolean>>({})
  const apps = Array.from(new Map(workspace.accessRules.map((rule) => [rule.appId, rule.appName])))

  const enabledFor = (appId: string, category: MemoryCategory) => {
    const key = `${appId}:${category}`
    return key in overrides ? overrides[key] : Boolean(workspace.accessRules.find((rule) => rule.appId === appId && rule.category === category)?.enabled)
  }

  const toggle = (appId: string, category: MemoryCategory) => {
    const next = !enabledFor(appId, category)
    setOverrides((current) => ({ ...current, [`${appId}:${category}`]: next }))
    void updateAccess(appId, category, next)
  }

  return (
    <section className={styles.page} aria-labelledby="access-title">
      <header className={styles.pageHeader}>
        <div>
          <span className={styles.eyebrow}>MEMORY PERMISSIONS</span>
          <h1 id="access-title">어떤 AI가, 무엇을 기억할 수 있나요?</h1>
          <p>기억은 하나지만 접근 범위는 도구마다 다릅니다. 범주 단위로 안전하게 나누세요.</p>
        </div>
        <div className={styles.securityBadge}><ShieldCheck size={15} /><span><strong>기기 내 암호화</strong><small>권한 변경은 즉시 적용됩니다</small></span></div>
      </header>

      <div className={styles.accessSummary}>
        <div><LockKeyhole size={15} /><span><strong>{apps.length}개 AI 연결됨</strong><small>개인 기억은 기본적으로 비공개입니다.</small></span></div>
        <p><i /> 모든 권한 정상</p>
      </div>

      <div className={`${styles.panel} ${styles.accessPanel}`}>
        <div className={styles.matrixHeader}>
          <div><span className={styles.eyebrow}>CONNECTED AI</span><strong>연결된 도구</strong></div>
          {categories.map(({ name, icon: Icon, note }) => <div key={name}><Icon size={14} /><strong>{name}</strong><small>{note}</small></div>)}
        </div>

        {apps.map(([appId, appName]) => {
          const meta = appMeta[appName] ?? appMeta.ChatGPT
          const Icon = meta.icon
          return (
            <div className={styles.matrixRow} key={appId}>
              <div className={styles.appIdentity}>
                <span className={styles.appIcon}><Icon size={17} /></span>
                <span><strong>{appName}</strong><small>{meta.description}</small></span>
                <em>{meta.badge}</em>
              </div>
              {categories.map(({ name }) => {
                const enabled = enabledFor(appId, name)
                return (
                  <div className={styles.ruleCell} key={name}>
                    <button type="button" role="switch" aria-checked={enabled} aria-label={`${appName} ${name} 기억`} className={styles.switch} onClick={() => toggle(appId, name)}><span /></button>
                    <small>{enabled ? '허용됨' : '차단됨'}</small>
                  </div>
                )
              })}
            </div>
          )
        })}
      </div>

      <footer className={styles.accessFooter}>
        <span><Check size={13} /> 설정은 이 브라우저의 Memory OS에 저장됩니다.</span>
        <span>최근 권한 검토 · 오늘</span>
      </footer>
    </section>
  )
}

import { AlertTriangle, Archive, Database, Download, Fingerprint, HardDrive, RefreshCcw, ShieldCheck } from 'lucide-react'
import { useMemory } from '../state/MemoryContext'
import styles from './UtilityPages.module.css'

export function SettingsPage() {
  const { workspace, resetDemo } = useMemory()
  const activeMemories = workspace.memories.filter((memory) => memory.state !== 'archived').length

  return (
    <section className={styles.page} aria-labelledby="settings-title">
      <header className={styles.pageHeader}>
        <div>
          <span className={styles.eyebrow}>SYSTEM SETTINGS</span>
          <h1 id="settings-title">기억의 원본은 당신에게 있습니다</h1>
          <p>Memory OS가 보관하는 데이터의 상태를 확인하고 내보내거나 초기화할 수 있습니다.</p>
        </div>
        <div className={styles.headerStatus}><span /> SYSTEM HEALTHY</div>
      </header>

      <div className={styles.settingsGrid}>
        <div className={styles.settingsMain}>
          <section className={`${styles.panel} ${styles.settingsSection}`} aria-labelledby="data-title">
            <div className={styles.sectionHeading}><span className={styles.iconTile}><Database size={16} /></span><div><span className={styles.eyebrow}>DATA & STORAGE</span><h2 id="data-title">내 기억 데이터</h2></div></div>
            <div className={styles.storageMeter}>
              <div className={styles.storageLabel}><span><strong>기억 저장소</strong><small>로컬 인덱스 · 암호화됨</small></span><b>24.8 MB</b></div>
              <div className={styles.meterTrack}><span /></div>
              <div className={styles.storageStats}><span><b>{workspace.memoryCount}</b> 전체 기억</span><span><b>{activeMemories}</b> 활성 기억</span><span><b>{workspace.week.archived}</b> 이번 주 보관</span></div>
            </div>
            <div className={styles.settingsRows}>
              <div className={styles.settingsRow}><span className={styles.rowIcon}><Download size={15} /></span><span><strong>내 기억 내보내기</strong><small>JSON 형식으로 기억과 근거를 내려받습니다.</small></span><button type="button" className={styles.secondaryButton}>내보내기</button></div>
              <div className={styles.settingsRow}><span className={styles.rowIcon}><Archive size={15} /></span><span><strong>보관된 기억 관리</strong><small>응답에 사용되지 않는 오래된 기억을 검토합니다.</small></span><button type="button" className={styles.secondaryButton}>열기</button></div>
            </div>
          </section>

          <section className={`${styles.panel} ${styles.settingsSection}`} aria-labelledby="privacy-title">
            <div className={styles.sectionHeading}><span className={styles.iconTile}><Fingerprint size={16} /></span><div><span className={styles.eyebrow}>PRIVACY</span><h2 id="privacy-title">개인정보 및 보안</h2></div></div>
            <div className={styles.privacyCards}>
              <div><ShieldCheck size={17} /><span><strong>기기 내 암호화</strong><small>저장된 기억은 로컬 키로 보호됩니다.</small></span><em>ON</em></div>
              <div><HardDrive size={17} /><span><strong>로컬 우선 저장</strong><small>허용한 AI에만 필요한 범위를 전달합니다.</small></span><em>ON</em></div>
            </div>
          </section>
        </div>

        <aside className={styles.settingsAside}>
          <section className={`${styles.panel} ${styles.systemCard}`}>
            <span className={styles.eyebrow}>MEMORY OS</span>
            <div className={styles.systemMark}><Database size={22} /></div>
            <h2>Memory OS 1.0</h2>
            <p>개인의 맥락을 투명하게 관리하는 로컬 기억 레이어</p>
            <dl><div><dt>동기화</dt><dd>방금</dd></div><div><dt>인덱스</dt><dd>정상</dd></div><div><dt>스키마</dt><dd>v1.4</dd></div></dl>
          </section>

          <section className={`${styles.panel} ${styles.dangerCard}`} aria-labelledby="reset-title">
            <div className={styles.dangerTitle}><AlertTriangle size={15} /><h2 id="reset-title">데모 데이터</h2></div>
            <p>모든 변경, 권한, 기억 상태를 처음 실행했을 때의 샘플로 되돌립니다.</p>
            <button type="button" className={styles.resetButton} onClick={() => void resetDemo()}><RefreshCcw size={14} />데모 초기화</button>
            <small>실제 계정 데이터에는 영향을 주지 않습니다.</small>
          </section>
        </aside>
      </div>
    </section>
  )
}

.page { width: 100%; height: 100%; min-height: 720px; overflow: auto; padding: 35px 40px 44px; background: radial-gradient(circle at 62% 12%, rgba(98,108,133,.08), transparent 29%), linear-gradient(145deg, #0d0f13, #090a0c 68%); }
.pageHeader { display: flex; align-items: flex-end; justify-content: space-between; max-width: 1180px; margin: 0 auto 27px; gap: 28px; }
.eyebrow { display: block; margin-bottom: 10px; color: var(--text-dim); font: 500 8.5px/1 'Space Grotesk'; letter-spacing: .18em; text-transform: uppercase; }
.pageHeader h1 { margin: 0; font: 400 28px/1.35 'Space Grotesk','Noto Sans KR'; letter-spacing: -.035em; }
.pageHeader p { max-width: 620px; margin: 9px 0 0; color: var(--text-dim); font-size: 10.5px; font-weight: 300; line-height: 1.7; }
.headerStatus { display: flex; align-items: center; gap: 8px; padding: 9px 12px; border: 1px solid var(--line); border-radius: 18px; color: var(--text-dim); font: 500 8px/1 'Space Grotesk'; letter-spacing: .12em; white-space: nowrap; }
.headerStatus > span { width: 5px; height: 5px; border-radius: 50%; background: var(--paper); box-shadow: 0 0 9px rgba(242,239,228,.8); }
.panel { border: 1px solid var(--line); border-radius: 13px; background: rgba(16,18,22,.84); box-shadow: 0 20px 60px rgba(0,0,0,.14); }
.iconTile { display: grid; place-items: center; width: 32px; height: 32px; flex: none; border: 1px solid var(--line-strong); border-radius: 9px; color: var(--text-soft); background: rgba(242,239,228,.025); }
.primaryButton,.secondaryButton,.textButton,.resetButton { display: inline-flex; align-items: center; justify-content: center; min-height: 34px; border-radius: 8px; font-size: 9.5px; font-weight: 500; cursor: pointer; transition: 160ms var(--ease); }
.primaryButton { border: 1px solid var(--paper); color: var(--ink); background: var(--paper); }
.primaryButton:hover { background: white; }
.secondaryButton { padding: 0 13px; border: 1px solid var(--line-strong); color: var(--text-soft); background: transparent; }
.secondaryButton:hover { color: var(--text); background: rgba(242,239,228,.06); }
.textButton { border: 0; color: var(--text-dim); background: transparent; }

/* Chat */
.chatGrid { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(320px, .75fr); max-width: 1180px; height: calc(100vh - 156px); min-height: 555px; max-height: 720px; margin: 0 auto; gap: 14px; }
.conversation { display: flex; min-width: 0; flex-direction: column; overflow: hidden; }
.panelHeader { display: flex; align-items: center; justify-content: space-between; min-height: 64px; padding: 0 18px; border-bottom: 1px solid var(--line); }
.panelIdentity { display: flex; align-items: center; gap: 11px; }
.panelIdentity > div { display: flex; flex-direction: column; gap: 5px; }
.panelIdentity strong { font: 500 11px/1 'Space Grotesk'; }
.panelIdentity small { color: var(--text-dim); font-size: 8.5px; }
.online { display: flex; align-items: center; gap: 7px; color: var(--text-dim); font: 500 7.5px/1 'Space Grotesk'; letter-spacing: .12em; }
.online i { width: 5px; height: 5px; border-radius: 50%; background: var(--paper); }
.thread { flex: 1; overflow: auto; padding: 22px 26px; }
.dateDivider { display: flex; align-items: center; gap: 10px; margin: 0 0 22px; color: var(--text-dim); font-size: 8px; }
.dateDivider::before,.dateDivider::after { height: 1px; flex: 1; background: var(--line); content: ''; }
.assistantMessage,.userMessage { display: flex; align-items: flex-start; gap: 11px; max-width: 78%; margin-bottom: 21px; }
.userMessage { margin-left: auto; text-align: right; }
.avatar { display: grid; place-items: center; width: 29px; height: 29px; flex: none; border: 1px solid var(--line-strong); border-radius: 50%; color: var(--text-soft); background: var(--surface-2); }
.userAvatar { color: var(--ink); border-color: var(--paper); background: var(--paper); }
.assistantMessage p,.userMessage p { margin: 0; padding: 12px 14px; border: 1px solid var(--line); border-radius: 3px 12px 12px; color: var(--text-soft); background: rgba(242,239,228,.025); font-size: 10px; line-height: 1.75; text-align: left; }
.userMessage p { color: var(--ink); border-color: var(--paper); border-radius: 12px 3px 12px 12px; background: var(--paper); }
.assistantMessage time,.userMessage time { display: block; margin-top: 6px; color: var(--text-dim); font: 400 7.5px/1 'Space Grotesk'; }
.composer { display: flex; align-items: center; gap: 10px; margin: 0 16px 16px; padding: 7px 7px 7px 13px; border: 1px solid var(--line-strong); border-radius: 11px; color: var(--text-dim); background: rgba(242,239,228,.025); }
.composer input { min-width: 0; flex: 1; border: 0; outline: 0; color: var(--text); background: transparent; font-size: 10px; }
.composer input::placeholder { color: var(--text-dim); }
.composer input:focus-visible { outline: 0; }
.keyHint { padding: 4px 6px; border: 1px solid var(--line); border-radius: 5px; font: 500 7px/1 'Space Grotesk'; }
.composer button { display: grid; place-items: center; width: 31px; height: 31px; border: 0; border-radius: 8px; color: var(--ink); background: var(--paper); cursor: pointer; }
.inspector { display: flex; min-width: 0; flex-direction: column; border: 1px solid var(--line); border-radius: 13px; overflow: hidden; background: rgba(11,12,15,.8); }
.inspectorIntro { display: flex; align-items: center; gap: 11px; padding: 16px; border-bottom: 1px solid var(--line); }
.inspectorIntro .eyebrow { margin-bottom: 6px; }
.inspectorIntro h2 { margin: 0; font: 500 12px/1 'Space Grotesk','Noto Sans KR'; }
.emptyState { display: flex; flex: 1; align-items: center; flex-direction: column; justify-content: center; padding: 36px; text-align: center; }
.emptyOrbit { position: relative; display: grid; place-items: center; width: 72px; height: 72px; margin-bottom: 20px; border: 1px solid var(--line); border-radius: 50%; color: var(--text-dim); }
.emptyOrbit span { position: absolute; width: 48px; height: 48px; border: 1px dashed var(--line-strong); border-radius: 50%; }
.emptyState strong { font-size: 10.5px; font-weight: 500; }
.emptyState p { max-width: 260px; margin: 9px 0 0; color: var(--text-dim); font-size: 9px; line-height: 1.7; }
.correctionCard { margin: 16px; padding: 16px; border: 1px solid var(--line-strong); border-radius: 11px; background: rgba(242,239,228,.025); animation: rise 240ms var(--ease); }
.detected { display: flex; align-items: center; gap: 9px; padding-bottom: 14px; border-bottom: 1px solid var(--line); }
.detected > span,.scopeNote > span { display: flex; flex: 1; flex-direction: column; gap: 5px; }
.detected strong,.scopeNote strong { font-size: 10px; font-weight: 500; }
.detected small,.scopeNote small { color: var(--text-dim); font-size: 8px; }
.changePreview { display: grid; grid-template-columns: 1fr auto; align-items: center; padding: 15px 0; border-bottom: 1px solid var(--line); column-gap: 8px; }
.changePreview span { color: var(--text-dim); font: 500 7px/1 'Space Grotesk'; letter-spacing: .13em; }
.changePreview p { grid-column: 1 / -1; margin: 6px 0 12px; padding: 9px 10px; border-radius: 7px; color: var(--text-soft); background: rgba(242,239,228,.035); font-size: 9px; line-height: 1.55; }
.changePreview p:last-child { margin-bottom: 0; color: var(--text); border: 1px solid var(--line); }
.changePreview svg { grid-column: 2; grid-row: 1; color: var(--text-dim); }
.scopeNote { display: flex; gap: 8px; padding: 13px 0; color: var(--text-soft); }
.correctionActions { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
