import { Sparkles } from '../icons'
import { useState, type CSSProperties } from 'react'
import { useMemory } from '../state/MemoryContext'
import styles from './HomePage.module.css'

const rings = [
  ['여백 많은 UI', '속도 우선', '디카페인', '290mm', '다크 모드'],
  ['Swift 재도입', '해커톤 몰입', 'B2B 탐색', 'MVP 이틀', '파스텔 거부', 'M2 Air', '협업 SaaS'],
  ['AI 코딩 도구', '완성도 타협 안 함', '정보 밀도 낮게', '프로젝트 3.4개', 'Flutter 감소', '휴학 고민', 'B2C 창업', '근거 14개'],
]

export function HomePage() {
  const { workspace } = useMemory()
  const [activeQuestion, setActiveQuestion] = useState(0)
  const selected = workspace.orbitQuestions[activeQuestion]

  return (
    <section className={styles.page} aria-labelledby="orbit-title">
      <header className={styles.header}>
        <div><span className={styles.eyebrow}>YOUR MEMORY · {workspace.memoryCount}</span><h1 id="orbit-title">지금 당신은 이렇게 생겼습니다</h1></div>
        <div className={styles.week}>이번 주 기억 변화 <b>{workspace.week.strengthened + workspace.week.archived + workspace.week.merged}</b><span>· 판단 {workspace.week.pending}</span></div>
      </header>

      <div className={styles.orbitStage}>
        <div className={`${styles.ambient} visual-blur`} />
        <div className={`${styles.grain} visual-extra`} />
        {rings.map((words, ringIndex) => (
          <div key={ringIndex} className={`${styles.ring} ${styles[`ring${ringIndex + 1}`]}`}>
            <div className={styles.ringLine} />
            {words.map((word, index) => {
              const angle = (360 / words.length) * index
              return <span key={word} style={{ '--angle': `${angle}deg` } as CSSProperties}>{word}</span>
            })}
          </div>
        ))}
        <div className={styles.coreGlow} />
        <div className={styles.core}><Sparkles size={16} /><span>MEMORY OS</span></div>
        <div className={styles.answer} aria-live="polite"><p>{selected.answer}</p><span>{selected.meta}</span></div>
        <span className={`${styles.pulse} ${styles.pulseOne} visual-extra`}>새 기억 · Swift 프로젝트 시작</span>
        <span className={`${styles.pulse} ${styles.pulseTwo} visual-extra`}>강화됨 · 여백 선호 +19</span>
      </div>

      <div className={styles.composerArea}>
        <div className={styles.chips}>
          {workspace.orbitQuestions.map((item, index) => <button key={item.id} aria-pressed={index === activeQuestion} onClick={() => setActiveQuestion(index)}>{item.question}</button>)}
        </div>
      </div>
    </section>
  )
}

@keyframes spin { to { transform: translate(-50%, -50%) rotate(360deg); } }
@keyframes spinBack { to { transform: translate(-50%, -50%) rotate(-360deg); } }
@keyframes breathe { 50% { transform: translate(-50%, -50%) scale(1.08); opacity: 1; } }
@keyframes surface { 0%,100% { opacity: 0; transform: translateY(8px); } 14%,70% { opacity: 1; transform: translateY(0); } }

.page { position: relative; width: 100%; height: 100%; min-height: 720px; overflow: hidden; background: radial-gradient(circle at 55% 47%, #12151b 0, #0a0b0e 45%, #08090b 75%); }
.header { position: absolute; z-index: 20; top: 34px; right: 38px; left: 40px; display: flex; align-items: flex-start; justify-content: space-between; }
.eyebrow { color: var(--text-dim); font: 500 11px/1 'Space Grotesk'; letter-spacing: .2em; }
.header h1 { margin: 12px 0 0; font: 500 30px/1.2 'Space Grotesk','Noto Sans KR'; letter-spacing: -.04em; }
.week { display: flex; align-items: center; gap: 7px; min-height: 38px; padding: 0 14px; border: 1px solid var(--line-strong); border-radius: 20px; color: var(--text-soft); background: rgba(16,18,22,.88); font-size: 12px; }
.week b { color: var(--text); font: 600 14px/1 'Space Grotesk'; }
.week span { color: var(--text-dim); }
.orbitStage { position: absolute; inset: 72px 0 112px; }
.ambient { position: absolute; left: 50%; top: 50%; width: 560px; height: 560px; border-radius: 50%; background: radial-gradient(circle, rgba(242,239,228,.06), rgba(69,79,101,.03) 48%, transparent 70%); filter: blur(30px); transform: translate(-50%,-50%); }
.grain { position: absolute; inset: 0; opacity: .16; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.19'/%3E%3C/svg%3E"); mix-blend-mode: soft-light; }
.ring { position: absolute; left: 50%; top: 50%; border-radius: 50%; transform: translate(-50%,-50%); }
.ring1 { width: 260px; height: 260px; animation: spin 44s linear infinite; }
.ring2 { width: 430px; height: 430px; animation: spinBack 68s linear infinite; }
.ring3 { width: 610px; height: 610px; animation: spin 94s linear infinite; }
.ringLine { position: absolute; inset: 0; border: 1px solid rgba(242,239,228,.08); border-radius: 50%; box-shadow: inset 0 0 60px rgba(242,239,228,.015); }
.ring span { --radius: 130px; position: absolute; left: 50%; top: 50%; color: rgba(242,239,228,.88); font-size: 13px; white-space: nowrap; transform: rotate(var(--angle)) translateX(var(--radius)) rotate(calc(-1 * var(--angle))); transform-origin: 0 0; }
.ring2 span { --radius: 215px; color: rgba(242,239,228,.62); font-size: 12px; }
.ring3 span { --radius: 305px; color: rgba(242,239,228,.35); font-size: 11px; }
.coreGlow { position: absolute; left: 50%; top: 50%; width: 110px; height: 110px; border-radius: 50%; background: rgba(242,239,228,.07); filter: blur(26px); transform: translate(-50%,-50%); animation: breathe 4.5s ease-in-out infinite; }
.core { position: absolute; left: 50%; top: 50%; display: flex; align-items: center; justify-content: center; width: 66px; height: 66px; border: 1px solid rgba(242,239,228,.5); border-radius: 50%; color: var(--ink); background: var(--paper); box-shadow: 0 0 70px rgba(242,239,228,.18); transform: translate(-50%,-50%); }
.core svg { position: absolute; }
.core span { position: absolute; top: calc(100% + 12px); color: var(--text-dim); font: 500 10px/1 'Space Grotesk'; letter-spacing: .16em; white-space: nowrap; }
.answer { position: absolute; left: 50%; top: calc(50% + 92px); width: 470px; padding: 14px 18px 13px; border: 1px solid rgba(255,255,255,.1); border-radius: 16px; text-align: center; background: rgba(10,12,16,.68); box-shadow: inset 0 1px 0 rgba(255,255,255,.06), 0 18px 48px rgba(0,0,0,.22); backdrop-filter: blur(22px) saturate(125%); transform: translateX(-50%); }
.answer p { margin: 0; font-size: 15px; font-weight: 400; line-height: 1.7; text-shadow: 0 2px 18px #000; }
.answer span { display: block; margin-top: 9px; color: var(--text-dim); font: 400 11px/1 'Space Grotesk'; letter-spacing: .06em; }
.pulse { position: absolute; padding: 9px 13px; border: 1px solid var(--line); border-radius: 18px; color: var(--text-soft); background: rgba(16,18,22,.88); font-size: 11px; animation: surface 8s var(--ease) infinite; }
.pulseOne { left: 19%; top: 23%; }.pulseTwo { right: 16%; top: 37%; animation-delay: 2.8s; }.pulseThree { left: 28%; bottom: 15%; animation-delay: 5.4s; }
.composerArea { position: absolute; z-index: 20; right: 0; bottom: 28px; left: 0; display: flex; flex-direction: column; align-items: center; gap: 11px; }
.chips { display: flex; gap: 7px; }
.chips button { padding: 9px 15px; border: 1px solid var(--line-strong); border-radius: 20px; color: var(--text-soft); background: rgba(11,12,15,.78); font-size: 13px; cursor: pointer; transition: 180ms var(--ease); }
.chips button[aria-pressed='true'] { color: var(--ink); border-color: var(--paper); background: var(--paper); }
.composer { display: flex; align-items: center; gap: 11px; width: 520px; padding: 14px 17px; border: 1px solid var(--glass-border); border-radius: 26px; color: var(--text-soft); background: var(--glass-surface); box-shadow: var(--glass-highlight), 0 18px 44px rgba(0,0,0,.2); font-size: 13px; backdrop-filter: blur(22px) saturate(125%); }
.composer span { flex: 1; }.composer svg:last-child { opacity: .55; }
.scrollHint { position: absolute; right: 28px; bottom: 24px; display: flex; align-items: center; gap: 7px; color: rgba(242,239,228,.22); font-size: 8px; }

@media (max-height: 760px) { .page { min-height: 720px; } .ring3 { width: 520px; height: 520px; } .ring3 span { --radius: 260px; } }

import { ArrowRight, Check, Clock3, X } from '../icons'
import { useState } from 'react'
import { useLocation } from 'react-router-dom'
import type { MemoryChange } from '../domain/memory'
import { useMemory } from '../state/MemoryContext'
import screen from './Screen.module.css'
import styles from './ChangesPage.module.css'

const kindLabel: Record<MemoryChange['kind'], string> = {
  changed: 'CHANGED', fading: 'FADING', duplicate: 'DUPLICATE', contradiction: 'CONTRADICTION',
}

export function ChangesPage() {
  const { workspace, resolveChange } = useMemory()
  const location = useLocation()
  const [modal, setModal] = useState<'diff' | 'review' | 'cleanup' | null>(() => (location.state as { openCleanup?: boolean } | null)?.openCleanup ? 'cleanup' : null)
  const [cleanupIndex, setCleanupIndex] = useState(0)
  const [showAll, setShowAll] = useState(false)
  const [showEvidence, setShowEvidence] = useState(false)
  const pending = workspace.changes.filter((item) => item.status === 'pending')
  const change = workspace.changes[0]
  const cleanup = workspace.memories.filter((item) => item.state === 'fading' || item.state === 'review').slice(0, 3)

  const advanceCleanup = () => {
    if (cleanupIndex >= cleanup.length - 1) { setModal(null); setCleanupIndex(0) }
    else setCleanupIndex((value) => value + 1)
  }

  return (
    <section className={screen.screen}>
      <div className={screen.inner}>
        <div className={screen.topRow}>
          <header><span className={screen.eyebrow}>8월 10일 — 8월 16일</span><h1 className={screen.heading}>이번 주, AI가 당신에 대해 이해한 것이<br />이렇게 달라졌습니다.</h1></header>
          <button className={screen.buttonGhost} onClick={() => setModal('cleanup')}><Clock3 size={14} />47초 정리</button>
        </div>

        <div className={styles.summaryBar}>
          <div><span>이번 주 Memory OS가 대부분을 정리했습니다.</span><strong>전체 {workspace.memoryCount}개 중 94% 자동 정리 · 직접 판단 {pending.length}건</strong></div>
          <button className={screen.buttonGhost} onClick={() => setModal('review')}>빠르게 판단하기 <ArrowRight size={14} /></button>
        </div>

        <div className={styles.sectionHead}><span>가장 중요한 변화</span><b>1건</b><div /></div>
        <div className={styles.feed} id="changes-feed">
          {(showAll ? workspace.changes : workspace.changes.slice(0, 1)).map((item) => (
            <article key={item.id} className={`${styles.changeCard} ${item.status === 'resolved' ? styles.resolved : ''}`}>
              <div className={styles.cardMeta}><span>{kindLabel[item.kind]}</span><small>{item.meta}</small></div>
              <h2>{item.title}</h2><p>{item.description}</p>
              {item.evidence.length > 0 && <ul>{item.evidence.slice(0, 2).map((entry) => <li key={entry}>{entry}</li>)}</ul>}
              <div className={styles.cardActions}>
                {item.status === 'resolved' ? <span className={styles.done}><Check size={13} /> 반영됨</span> : <>
                  <button className={screen.button} onClick={() => item.id === 'flutter-change' ? setModal('diff') : void resolveChange(item.id, 'accept')}>{item.kind === 'changed' ? '기억 업데이트' : item.kind === 'fading' ? '지금 보관' : item.kind === 'duplicate' ? '하나로 병합' : '조건 저장'}</button>
                  {item.id === 'flutter-change' && <button className={screen.buttonGhost} onClick={() => setModal('diff')}>변경 내용 보기</button>}
                  <button className={screen.textButton} onClick={() => void resolveChange(item.id, 'reject')}>아직 유효해요</button>
                </>}
              </div>
            </article>
          ))}
        </div>
        <button className={styles.disclosure} aria-expanded={showAll} aria-controls="changes-feed" onClick={() => setShowAll((value) => !value)}>{showAll ? '간단히 보기' : `나머지 ${workspace.changes.length - 1}개 보기`}<ArrowRight size={14} /></button>
        <p className={styles.footnote}>지금 결정하지 않아도 괜찮습니다. 언제든 되돌릴 수 있습니다.</p>
      </div>

      {modal === 'diff' && <div className={styles.backdrop} onMouseDown={() => setModal(null)}><div className={styles.dialog} role="dialog" aria-modal="true" aria-label="이해 업데이트 제안" onMouseDown={(event) => event.stopPropagation()}>
        <div className={styles.dialogTop}><span>이해 업데이트 제안</span><button autoFocus aria-label="닫기" onClick={() => setModal(null)}><X size={16} /></button></div>
        <h2>AI가 당신에 대한 이해를<br />이렇게 바꾸려 합니다.</h2>
        <div className={styles.diff}><div><span>BEFORE</span><p>{change.before}</p></div><ArrowRight size={18} /><div><span>AFTER</span><p>{change.after}</p></div></div>
        <p className={styles.evidence}>근거 {change.evidence.length + 11}개 · 최근 90일 대화에서 수집</p>
        {showEvidence && <ul className={styles.dialogEvidence}>{change.evidence.map((item) => <li key={item}>{item}</li>)}</ul>}
        <div className={styles.dialogActions}><button className={screen.button} onClick={async () => { await resolveChange(change.id, 'accept'); setModal(null) }}>이 이해를 승인</button><button className={screen.buttonGhost} onClick={() => setModal(null)}>기존 유지</button><button className={screen.textButton} aria-expanded={showEvidence} onClick={() => setShowEvidence((value) => !value)}>{showEvidence ? '근거 접기' : '근거 더 보기'}</button></div>
      </div></div>}

      {modal === 'review' && <div className={styles.backdrop} onMouseDown={() => setModal(null)}><div className={`${styles.dialog} ${styles.reviewDialog}`} role="dialog" aria-modal="true" aria-label="판단 필요" onMouseDown={(event) => event.stopPropagation()}>
        <div className={styles.dialogTop}><span>판단 필요 · 1 / 2</span><button autoFocus onClick={() => setModal(null)}>나중에</button></div><h2>창업은 B2C 위주로 하고 싶음</h2><span className={styles.outdated}>아마도 낡은 기억</span><p>8개월 전에 만들어진 기억입니다. 그 이후 B2B 아이디어를 7번 탐색하고 협업 SaaS를 3번 검토했습니다.</p><div className={styles.dialogActions}><button className={screen.button} onClick={() => setModal(null)}>맞아요, 약화시켜요</button><button className={screen.buttonGhost} onClick={() => setModal(null)}>아직 유효해요</button></div>
      </div></div>}

      {modal === 'cleanup' && <div className={styles.cleanupBackdrop} role="dialog" aria-modal="true" aria-label="기억 정리"><div className={styles.cleanupTop}><span>MEMORY CLEANUP</span><b>{cleanupIndex + 1} / {cleanup.length}</b></div><div className={styles.cleanupStack}><i /><i /><div className={styles.cleanupCard}><span>{cleanup[cleanupIndex].category} · {cleanup[cleanupIndex].ageLabel}</span><h2>{cleanup[cleanupIndex].text}</h2><p>최근 답변에 미치는 영향이 낮아졌습니다. 이 기억을 계속 유지할까요?</p><div><button autoFocus className={screen.buttonGhost} onClick={advanceCleanup}>← 잊어도 돼</button><button className={screen.button} onClick={advanceCleanup}>유지 →</button></div></div></div><button className={screen.textButton} onClick={() => setModal(null)}>그만하기 · 나머지는 AI가 알아서</button></div>}
    </section>
  )
}

import type { MemoryWorkspace } from '../domain/memory'

export const demoWorkspace: MemoryWorkspace = {
  memoryCount: 612,
  week: { strengthened: 12, archived: 18, merged: 5, pending: 2 },
  memories: [
    { id: 'ai-tools', text: 'AI 코딩 도구를 상시 사용함', category: '코딩', ageBucket: 'now', ageLabel: '2일 전', strength: 0.98, usageCount: 42, pinned: false, state: 'strong' },
    { id: 'swift', text: 'Swift를 다시 프로젝트에 도입함', category: '코딩', ageBucket: '30d', ageLabel: '3주 전', strength: 0.76, usageCount: 18, pinned: false, state: 'strong' },
    { id: 'flutter', text: 'Flutter를 주 개발 프레임워크로 선호함', category: '코딩', ageBucket: '90d', ageLabel: '5개월 전', strength: 0.42, usageCount: 26, pinned: false, state: 'review' },
